// CODE NODE: CLEAN INTERNAL DATA (REVISI)
const results = [];

for (const item of $input.all()) {
  const json = item.json;

  // 1. Filter Tipe Transaksi
  const tipe = json['Tipe Transaksi'];
  if (tipe !== 'Pembayaran' && tipe !== 'Pengeluaran' && tipe !== 'Penerimaan') {
    continue; 
  }

  // 2. Bersihkan Tanggal (Hapus spasi & format ulang)
  // Asumsi format di CSV/Sheet: DD/MM/YYYY
  const rawDate = (json['Tanggal Transaksi'] || '').toString().trim();
  const dateParts = rawDate.split('/');
  // Pastikan date valid
  if (dateParts.length !== 3) continue;

  const cleanDate = `${dateParts[2]}-${dateParts[1]}-${dateParts[0]}`;

  // 3. PENTING: Bersihkan Angka dari titik (.) atau koma (,)
  // Kita ubah jadi string dulu, hapus semua yang BUKAN angka, baru parse
  const rawAmount = (json['Jumlah (IDR)'] || '0').toString();
  const cleanAmount = parseInt(rawAmount.replace(/[^0-9]/g, ''));

  // 4. Buat Match Key
  const matchKey = `${cleanDate}_${cleanAmount}`;

  results.push({
    json: {
      ...json,
      clean_date: cleanDate,
      clean_amount: cleanAmount,
      match_key: matchKey,
      sumber: 'Internal'
    }
  });
}

return results;

// CODE NODE: CLEAN BANK DATA (REVISI)
const results = [];

for (const item of $input.all()) {
  const json = item.json;

  // 1. Bersihkan Tanggal
  const rawDate = (json['Tanggal Bank'] || '').toString().trim();
  const dateParts = rawDate.split('/');
  if (dateParts.length !== 3) continue;

  const cleanDate = `${dateParts[2]}-${dateParts[1]}-${dateParts[0]}`;

  // 2. PENTING: Bersihkan Angka (Hapus titik ribuan Rupiah)
  const rawAmount = (json['Jumlah (IDR)'] || '0').toString();
  // Regex ini menghapus apa saja yang bukan angka (termasuk titik/koma)
  const cleanAmount = parseInt(rawAmount.replace(/[^0-9]/g, ''));

  // 3. Buat Match Key
  const matchKey = `${cleanDate}_${cleanAmount}`;

  results.push({
    json: {
      ...json,
      clean_date: cleanDate,
      clean_amount: cleanAmount,
      match_key: matchKey,
      sumber: 'Bank'
    }
  });
}

return results;

// CODE NODE: ANALISA REKONSILIASI LENGKAP (tanpa Union)
const items = $input.all();
const grouped = {};

// 1. Group by match_key
for (const item of items) {
  const key = item.json.match_key;
  if (!grouped[key]) {
    grouped[key] = { sources: [], details: [] };
  }
  grouped[key].sources.push(item.json.sumber);
  grouped[key].details.push(item.json);
}

// 2. Bangun hasil analisa
const results = [];
for (const [key, group] of Object.entries(grouped)) {
  const hasInternal = group.sources.includes('Internal');
  const hasBank = group.sources.includes('Bank');

  let status, pesan, priority;
  if (hasInternal && hasBank) {
    status = 'MATCHED';
    pesan = '✅ Data klop (Cocok).';
    priority = 'Low';
  } else if (hasInternal && !hasBank) {
    status = 'MISSING IN BANK';
    pesan = '⚠️ Tercatat di Internal, tapi tidak ada di Bank.';
    priority = 'High';
  } else if (!hasInternal && hasBank) {
    status = 'UNRECORDED INTERNAL';
    pesan = '⚠️ Ada di Bank, tapi tidak tercatat di Internal.';
    priority = 'Medium';
  }

  const internal = group.details.find(d => d.sumber === 'Internal');
  const bank = group.details.find(d => d.sumber === 'Bank');
  const refDate = (internal || bank)?.clean_date;
  const amount = (internal || bank)?.clean_amount;

  results.push({
    json: {
      Tanggal: refDate,
      Nominal: amount,
      Status: status,
      Pesan: pesan,
      Prioritas: priority,
      Internal_ID: internal?.['ID Referensi'] || 'N/A',
      Bank_ID: bank?.['ID Transaksi Bank'] || 'N/A',
      Deskripsi: internal?.Deskripsi || bank?.['Deskripsi Transaksi'] || '-',
      Match_Key: key,
      Sources: group.sources.join(' + ')
    }
  });
}

return results;

const items = $input.all().map(i => i.json);
if (items.length === 0) return [];

const esc = s => String(s ?? '-').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmt = n => Number(n).toLocaleString('id-ID');
const cut = (s, n) => { s = String(s ?? '-'); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const short = { 'MATCHED': 'MATCHED', 'MISSING IN BANK': 'MISSING', 'UNRECORDED INTERNAL': 'UNRECORDED' };

// Judul otomatis sesuai isi data
const adaSelisih = items.some(r => r.Status !== 'MATCHED');
const judul = adaSelisih ? '🚨 LAPORAN SELISIH REKONSILIASI' : '✅ REKAPITULASI REKONSILIASI';

// Ringkasan
const count = {};
items.forEach(r => { count[r.Status] = (count[r.Status] || 0) + 1; });
const total = items.reduce((s, r) => s + (Number(r.Nominal) || 0), 0);
const ringkas = Object.entries(count).map(([k, v]) => k + ': ' + v).join(', ');
const head = '<b>' + judul + '</b>\n' + esc(ringkas) + '\nTotal: Rp ' + fmt(total) + '\n\n';

// Data tabel
const rows = items.map((r, i) => ({
  no: String(i + 1),
  tgl: r.Tanggal,
  nom: fmt(r.Nominal),
  st: short[r.Status] || r.Status,
  ket: cut(r.Deskripsi, 18)
}));
const cols = [['No', 'no', 'r'], ['Tanggal', 'tgl', 'l'], ['Nominal', 'nom', 'r'], ['Status', 'st', 'l'], ['Keterangan', 'ket', 'l']];
const w = cols.map(c => Math.max(c[0].length, ...rows.map(r => String(r[c[1]]).length)));
const pad = (s, width, a) => a === 'r' ? String(s).padStart(width) : String(s).padEnd(width);
const line = vals => vals.map((v, i) => pad(v, w[i], cols[i][2])).join(' | ');

const header = line(cols.map(c => c[0]));
const sep = w.map(x => '-'.repeat(x)).join('-+-');
const body = rows.map(r => line(cols.map(c => r[c[1]])));

// Pecah jika melebihi batas pesan Telegram
const LIMIT = 3500;
const base = head.length + header.length + sep.length + 20;
const msgs = [];
let cur = [];
let len = base;
for (const b of body) {
  if (len + b.length + 1 > LIMIT) { msgs.push(cur); cur = []; len = base; }
  cur.push(b);
  len += b.length + 1;
}
if (cur.length) msgs.push(cur);

return msgs.map((chunk, idx) => ({ json: {
  pesan: (idx === 0 ? head : '<b>Lanjutan (' + (idx + 1) + '/' + msgs.length + ')</b>\n\n')
       + '<pre>' + esc([header, sep, ...chunk].join('\n')) + '</pre>'
} }));

